import React, { useState, useEffect } from 'react';
import logoImg from "./logo.png";
function App() {
  const [appointments, setAppointments] = useState([]);
  const [healthUnits, setHealthUnits] = useState([]);
  const [loading, setLoading] = useState(true);

  // Estados simulados para os recursos de monitoramento descritos no layout do PDF
  const [healthMetrics] = useState({
    bpm: 76,
    sono: "7h 20m",
    estresse: "Baixo",
    iaRecommendation: "Seu nível de estresse reduziu 12% após a melhoria do sono. Excelente evolução! Continue mantendo a hidratação constante durante as rotas externas hoje."
  });

  useEffect(() => {
    // Busca dados do Back-end FastAPI simultaneamente
    Promise.all([
      fetch('http://localhost:8000/appointments').then(res => res.json()),
      fetch('http://localhost:8000/health-units').then(res => res.json())
    ])
    .then(([appointmentsData, unitsData]) => {
      setAppointments(appointmentsData);
      setHealthUnits(unitsData);
      setLoading(false);
    })
    .catch((err) => {
      console.error("Erro ao conectar com a API do Back-end:", err);
      setLoading(false);
    });
  }, []);

  return (
      <div style={styles.body}>
          {/* Barra de Navegação Superior Principal */}
          <header style={styles.navbar}>
              <div style={styles.brandContainer}>
  <div style={styles.logoContainer}>
    <img
      src={logoImg}
      alt="Logo Saúde Para Todos"
      style={styles.logoImage}
    />
  </div>
  <h1 style={styles.navTitle}>Saúde Para Todos</h1>
</div>
              <div style={styles.navLinks}>
                  <span style={styles.userBadge}>Painel do Administrador</span>
                  <button
                      style={styles.logoutButton}
                      onClick={() => alert("Sessão encerrada.")}
                  >
                      Sair
                  </button>
              </div>
          </header>

          <div style={styles.mainContainer}>
              {/* COLUNA DA ESQUERDA: Monitoramento Core & IA (Baseado no layout do PDF) */}
              <section style={styles.leftColumn}>
                  {/* Seção Inteligência Artificial */}
                  <div style={styles.iaCard}>
                      <div style={styles.iaHeader}>
                          <span style={{ fontSize: "20px" }}>✨</span>
                          <h3 style={styles.iaTitle}>
                              Recomendações Personalizadas de IA
                          </h3>
                      </div>
                      <p style={styles.iaText}>
                          {healthMetrics.iaRecommendation}
                      </p>
                  </div>

                  {/* Módulo Health Sync */}
                  <h2 style={styles.sectionHeading}>
                      Saúde Para Todos — Métricas Ativas
                  </h2>
                  <div style={styles.metricsGrid}>
                      <div style={styles.metricCard}>
                          <div style={styles.metricHeader}>
                              <span
                                  style={{ fontSize: "22px", color: "#e53e3e" }}
                              >
                                  ❤️
                              </span>
                              <span style={styles.metricLabel}>
                                  Batimentos Cardíacos
                              </span>
                          </div>
                          <p style={styles.metricValue}>
                              {healthMetrics.bpm}{" "}
                              <span style={styles.metricUnit}>BPM</span>
                          </p>
                          <span style={styles.metricStatusStable}>Estável</span>
                      </div>

                      <div style={styles.metricCard}>
                          <div style={styles.metricHeader}>
                              <span
                                  style={{ fontSize: "22px", color: "#3182ce" }}
                              >
                                  🌙
                              </span>
                              <span style={styles.metricLabel}>
                                  Monitoramento do Sono
                              </span>
                          </div>
                          <p style={styles.metricValue}>{healthMetrics.sono}</p>
                          <span style={styles.metricStatusStable}>
                              Qualidade Alta
                          </span>
                      </div>

                      <div style={styles.metricCard}>
                          <div style={styles.metricHeader}>
                              <span
                                  style={{ fontSize: "22px", color: "#dd6b20" }}
                              >
                                  ⚡
                              </span>
                              <span style={styles.metricLabel}>
                                  Nível de Estresse
                              </span>
                          </div>
                          <p style={styles.metricValue}>
                              {healthMetrics.estresse}
                          </p>
                          <span style={styles.metricStatusStable}>Normal</span>
                      </div>
                      <div style={styles.metricCard}>
                          <div style={styles.metricHeader}>
                              <span
                                  style={{ fontSize: "22px", color: "#dd6b20" }}
                              >
                                  📜
                              </span>
                              <span style={styles.metricLabel}>
                                  Recomendações
                              </span>
                          </div>
                          <p style={styles.metricValue}>
                              {healthMetrics.recomendacoes}
                          </p>
                          <span style={styles.metricStatusStable}>Normal</span>
                      </div>

                      <div style={styles.metricCard}>
                          <div style={styles.metricHeader}>
                              <span
                                  style={{ fontSize: "22px", color: "#dd6b20" }}
                              >
                                  ✍
                              </span>
                              <span style={styles.metricLabel}>
                                  Agendar Conulta
                              </span>
                          </div>
                          <p style={styles.metricValue}>
                              {healthMetrics.estresse}
                          </p>
                          <span style={styles.metricStatusStable}>Normal</span>
                      </div>

                      <div style={styles.metricCard}>
                          <div style={styles.metricHeader}>
                              <span
                                  style={{ fontSize: "22px", color: "#dd6b20" }}
                              >
                                  🚨
                              </span>
                              <span style={styles.metricLabel}>
                                  Emergência
                              </span>
                          </div>
                          <p style={styles.metricValue}>
                              {healthMetrics.estresse}
                          </p>
                          <span style={styles.metricStatusStable}>Normal</span>
                      </div>
                  </div>

                  {/* Ações Rápidas Acessíveis */}
                  <div style={styles.quickActionsContainer}>
                      <button
                          style={styles.primaryActionButton}
                          onClick={() =>
                              alert(
                                  "Formulário de marcação de consulta aberto!",
                              )
                          }
                      >
                          ➕ Agendar Nova Consulta
                      </button>
                      <button
                          style={styles.emergencyButton}
                          onClick={() =>
                              alert(
                                  "Disparando alertas de emergência para contatos de confiança...",
                              )
                          }
                      >
                          🚨 Alerta de Emergência
                      </button>
                  </div>
              </section>

              {/* COLUNA DA DIREITA: Consolidação de Dados e Unidades Móveis */}
              <section style={styles.rightColumn}>
                  <h2 style={styles.sectionHeading}>
                      Unidades Móveis em Operação
                  </h2>
                  <div style={styles.unitsList}>
                      {loading ? (
                          <p>Carregando unidades...</p>
                      ) : (
                          healthUnits.map((unit) => (
                              <div key={unit.id} style={styles.unitItem}>
                                  <div>
                                      <h4 style={styles.unitName}>
                                          🚐 {unit.name}
                                      </h4>
                                      <p style={styles.unitLocation}>
                                          {unit.location}
                                      </p>
                                  </div>
                                  <span style={styles.activeBadge}>
                                      {unit.status}
                                  </span>
                              </div>
                          ))
                      )}
                  </div>

                  <h2 style={styles.sectionHeading}>
                      <br />
                      Agendamentos Consolidados (Filas e Triagem)
                  </h2>
                  {loading ? (
                      <p>Carregando registros do ecossistema...</p>
                  ) : (
                      <div style={styles.tableWrapper}>
                          <table style={styles.table}>
                              <thead>
                                  <tr style={styles.tableHeaderRow}>
                                      <th style={styles.tableTh}>Paciente</th>
                                      <th style={styles.tableTh}>
                                          Atendimento
                                      </th>
                                      <th style={styles.tableTh}>Data/Hora</th>
                                      <th style={styles.tableTh}>Status</th>
                                  </tr>
                              </thead>
                              <tbody>
                                  {appointments.map((app) => (
                                      <tr key={app.id} style={styles.tableRow}>
                                          <td style={styles.patientNameTd}>
                                              {app.patient_name}
                                          </td>
                                          <td style={styles.tableTd}>
                                              {app.appointment_type}
                                          </td>
                                          <td style={styles.tableTd}>
                                              {app.date_time}
                                          </td>
                                          <td style={styles.tableTd}>
                                              <span style={styles.statusPill}>
                                                  {app.status}
                                              </span>
                                          </td>
                                      </tr>
                                  ))}
                              </tbody>
                          </table>
                      </div>
                  )}
              </section>
          </div>
      </div>
  );
}

